import java.util.Scanner;

public class lilu {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int totalChars = sc.nextInt();
        int maxSequence = 0;
        int wordCount = 0;
        String sequenceInput = sc.next();
        char[] sequenceArray = sequenceInput.toCharArray();
        boolean inParentheses = false;
        int currentSequenceLength = 0;
        int tempSequenceLength = 0;

        for (int index = 0; index < totalChars; index++) {
            char ch = sequenceArray[index];

            if (ch == '(') {
                inParentheses = true;
                if (tempSequenceLength != 0) {
                    maxSequence = Math.max(maxSequence, tempSequenceLength);
                    tempSequenceLength = 0;
                }
            } else if (ch == ')') {
                inParentheses = false;
            }

            if (inParentheses) {
                if (ch != '_' && ch != '(' && ch != ')') {
                    wordCount++;
                }
            } else {
                if (ch != '_' && ch != '(' && ch != ')') {
                    currentSequenceLength++;
                    if (index == totalChars - 1) {
                        maxSequence = Math.max(maxSequence, currentSequenceLength);
                    }
                } else {
                    if (currentSequenceLength != 0) {
                        maxSequence = Math.max(maxSequence, currentSequenceLength);
                        currentSequenceLength = 0;
                    }
                }
            }
        }
        System.out.println(maxSequence + " " + wordCount);
    }
}
